using UnityEngine;using System;using System.Linq;using System.Text;
public static class ValidateExitCoast{public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");var report=new StringBuilder();foreach(var source in UnityEngine.Object.FindObjectsByType<MotorollerController>(FindObjectsSortMode.None).Where(m=>!m.GetComponent<LawnmowerController>())){GameObject copy=null,floor=null,wall=null;int checks=0;void Check(bool ok,string m){if(!ok)throw new Exception(source.name+": "+m);checks++;}try{floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.localScale=new Vector3(200,1,200);copy=UnityEngine.Object.Instantiate(source.gameObject,new Vector3(10000,.02f,10000),Quaternion.identity);var b=copy.GetComponent<BicycleController>();var engine=copy.GetComponent<MotorollerController>();var parked=copy.GetComponentsInChildren<Collider>().First(c=>!(c is CharacterController));b.SetRidden(true);Physics.SyncTransforms();for(int i=0;i<300;i++)b.Drive(1,0,false,.02f);float speed=b.Speed;var p=copy.transform.position;b.SetRidden(false);Check(!b.IsRidden&&b.IsCoasting&&b.Speed==speed,"Exit preserves speed");Check(!parked.enabled,"Moving collider setup retained");b.TickUnoccupied(0);Check(copy.transform.position==p,"Pause does not advance coast");float prev=speed;for(int i=0;i<50;i++){b.TickUnoccupied(.02f);Physics.SyncTransforms();Check(b.Speed<=prev+.001f,"Speed decays monotonically");prev=b.Speed;}float distance=Vector3.Distance(copy.transform.position,p);Check(distance>.1f&&distance<speed*.8f,"Short forward coast "+distance);Check(!b.IsCoasting&&b.Speed==0&&parked.enabled,"Stops and restores parked collision");p=copy.transform.position;b.TickUnoccupied(.1f);Check(copy.transform.position==p,"Stays parked");b.SetRidden(true);for(int i=0;i<100;i++)b.Drive(-1,0,false,.02f);speed=b.Speed;b.SetRidden(false);p=copy.transform.position;b.TickUnoccupied(.02f);Check(copy.transform.position.z<p.z&&b.Speed<0,"Reverse momentum");speed=b.Speed;b.SetRidden(true);Check(!b.IsCoasting&&b.Speed==speed,"Remount retains speed");for(int i=0;i<100;i++)b.Drive(0,0,true,.02f);b.SetRidden(false);Check(!b.IsCoasting&&parked.enabled,"Stationary exit stays parked");
 b.SetRidden(true);for(int i=0;i<200;i++)b.Drive(1,0,false,.02f);using(var so=new UnityEditor.SerializedObject(engine)){float nose=(so.FindProperty("collisionCenter").vector3Value.z+so.FindProperty("collisionHalfExtents").vector3Value.z)*copy.transform.lossyScale.z;wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=copy.transform.position+new Vector3(0,2,nose+.8f);wall.transform.localScale=new Vector3(15,4,.1f);Physics.SyncTransforms();b.SetRidden(false);for(int i=0;i<60;i++){b.TickUnoccupied(.02f);Physics.SyncTransforms();}Check(copy.transform.position.z+nose<wall.transform.position.z-.04f,"Coasting stops before wall");Check(!b.IsCoasting,"Collision ends coast");}report.AppendLine(source.name+": PASS ("+checks+" checks), coast="+distance.ToString("F2")+"m");
 }finally{if(copy)UnityEngine.Object.DestroyImmediate(copy);if(floor)UnityEngine.Object.DestroyImmediate(floor);if(wall)UnityEngine.Object.DestroyImmediate(wall);}}
 System.IO.File.WriteAllText("output/Pickups/exit-coast-validation.txt",report.ToString());return report.ToString();}}
